import{_ as l,C as n,o as i,c,ak as d,E as o,j as a,a as r}from"./chunks/framework.DxrHb2fb.js";const q=JSON.parse('{"title":"Masonry 瀑布流","description":"","frontmatter":{},"headers":[],"relativePath":"components/masonry.md","filePath":"components/masonry.md","lastUpdated":1790043131000}'),h={name:"components/masonry.md"};function s(u,e,b,p,m,x){const t=n("XhDemo");return i(),c("div",null,[e[0]||(e[0]=d('<h1 id="masonry-瀑布流" tabindex="-1">Masonry 瀑布流 <a class="header-anchor" href="#masonry-瀑布流" aria-label="Permalink to &quot;Masonry 瀑布流&quot;">​</a></h1><p>将等宽、不等高的内容排列为瀑布流。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/masonry" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/masonry.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/masonry" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/masonry" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/masonry.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>按最短列排列卡片</p>',5)),o(t,{src:"masonry/01-basic"}),e[1]||(e[1]=d('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;masonry&quot;</code>：<strong><code>root</code></strong> · <strong><code>column</code></strong> · <code>item</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="响应式列" tabindex="-1">响应式列 <a class="header-anchor" href="#响应式列" aria-label="Permalink to &quot;响应式列&quot;">​</a></h3><p>根据容器宽度调整列数</p>',6)),o(t,{src:"masonry/02-columns"}),e[2]||(e[2]=a("h3",{id:"间距",tabindex:"-1"},[r("间距 "),a("a",{class:"header-anchor",href:"#间距","aria-label":'Permalink to "间距"'},"​")],-1)),e[3]||(e[3]=a("p",null,"设置列与项目之间的间距",-1)),o(t,{src:"masonry/03-gap"}),e[4]||(e[4]=a("h3",{id:"顺序排列",tabindex:"-1"},[r("顺序排列 "),a("a",{class:"header-anchor",href:"#顺序排列","aria-label":'Permalink to "顺序排列"'},"​")],-1)),e[5]||(e[5]=a("p",null,"按文档顺序逐列填充",-1)),o(t,{src:"masonry/04-sequential"}),e[6]||(e[6]=d('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>展示图片墙、卡片流或长短不一的摘要。</li><li>希望内容按最短列排列并减少空白。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>等高或跨列内容使用<a href="./grid">栅格</a>。</li><li>单轴排列使用<a href="./flex">弹性布局</a>。</li><li>大量数据使用<a href="./virtualizer">虚拟滚动</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>默认按最短列排列，也支持按顺序逐列填充。</li><li>支持固定列数和响应式列数。</li><li>支持五档行列间距。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>常与<a href="./card">卡片</a>、<a href="./image">图片</a>或<a href="./skeleton">骨架屏</a>组合使用。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>图片应提供宽高或宽高比，减少加载后的重排。</li><li>避免在会重排的项目中放置不可恢复的交互状态。</li><li>Web Components 需按最大列数提供空的 <code>column</code> 节点。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>不要用 CSS 多栏替代瀑布流布局。</li><li>不要对有严格顺序的内容使用最短列策略。</li><li>不要用项目外边距代替 <code>gap</code>。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-masonry&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhMasonry</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/masonry.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>columns</code></td><td><code>MasonryColumns</code></td><td></td><td>列数，未提供时按三列。也接受断点对象 <code>{ base, sm, md, lg, xl }</code>，逐档写各自的列数， 未写的档沿用更窄的一档。换档依据容器自身的宽度，不是视口宽度。</td></tr><tr><td><code>gap</code></td><td><code>MasonryGap</code></td><td></td><td>列与列、项与项之间的间距档位：xs / sm / md / lg / xl，未提供时不留间距。档位对应的数值由皮肤决定。</td></tr><tr><td><code>sequential</code></td><td><code>boolean</code></td><td></td><td>按文档序逐列填充：项分段落入各列，阅读顺序仍是先走完左列，再走下一列。 未提供时最短列优先，视觉上更齐平，但相邻的两项未必相邻。</td></tr></tbody></table><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getColumnProps</code></td><td><code>(props: MasonryColumnProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: MasonryItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><ul><li>最短列策略会改变 DOM 顺序。</li><li>顺序有意义的内容使用 <code>sequential</code>。</li><li>需要稳定焦点顺序时使用<a href="./grid">栅格</a>。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/masonry.css</code> 使用 <code>[data-scope=&quot;masonry&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-gap</code></td><td>props.gap</td></tr><tr><td><code>root</code></td><td><code>data-sequential</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>column</code></td><td><code>data-index</code></td><td>String(column.index)</td></tr><tr><td><code>item</code></td><td><code>data-column</code></td><td>String(item.column)</td></tr><tr><td><code>item</code></td><td><code>data-index</code></td><td>String(item.index)</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-masonry-gap</code></td><td><code>column</code><br><code>root</code></td><td><code>gap</code></td><td><code>default</code><br><code>gap=lg</code><br><code>gap=md</code><br><code>gap=sm</code><br><code>gap=xl</code><br><code>gap=xs</code></td><td><code>--xh-layout-gap-lg</code><br><code>--xh-layout-gap-md</code><br><code>--xh-layout-gap-sm</code><br><code>--xh-layout-gap-xl</code><br><code>--xh-layout-gap-xs</code><br><code>--xh-space-0</code></td><td>masonry 的 column、root 部件 gap 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>本组件皮肤不含过渡与关键帧，也没有脚本驱动的动效：状态一变，外观立即到位。</p><h3 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h3><ul><li>响应式列数根据容器宽度计算。</li><li>内容或容器尺寸变化后自动重新排列。</li></ul><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><ul><li>列顺序和间距自动适配 RTL。</li></ul>',41))])}const f=l(h,[["render",s]]);export{q as __pageData,f as default};
